// Constants
const size_t LG_CKH_BUCKET_CELLS = (LG_CACHELINE - LG_SIZEOF_PTR - 1);
const size_t CKH_BUCKET_CELLS = (ZU(1) << LG_CKH_BUCKET_CELLS);
const unsigned MAX_ITERATIONS = 100; // Reasonable limit to prevent infinite loops

// Get the two possible buckets for the key
size_t hashes[2];
ckh->hash(argkey, hashes);
size_t bucket1 = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
size_t bucket2 = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);

// Start with the provided bucket
size_t current_bucket = argbucket;
const void* current_key = argkey;
const void* current_data = argdata;

// Temporary storage for evicted items
ckhc_t evicted;
bool evicted_valid = false;

unsigned iterations = 0;
while (iterations < MAX_ITERATIONS) {
    iterations++;

    // Try to insert into current bucket
    bool inserted = false;
    for (size_t i = 0; i < CKH_BUCKET_CELLS; i++) {
        size_t cell_index = JemallocUtils::ckh_cell_index(current_bucket, i);
        if (ckh->tab[cell_index].key == nullptr) {
            // Found empty slot, insert here
            ckh->tab[cell_index].key = current_key;
            ckh->tab[cell_index].data = current_data;
            ckh->count++;
#ifdef CKH_COUNT
            ckh->ninserts++;
#endif
            return false; // Success
        }
    }

    // If we get here, bucket is full - need to evict
    // Choose a random cell to evict
    size_t evict_cell = JemallocUtils::ckh_prng(&ckh->prng_state) % CKH_BUCKET_CELLS;
    size_t evict_index = JemallocUtils::ckh_cell_index(current_bucket, evict_cell);

    // Save evicted item
    evicted.key = ckh->tab[evict_index].key;
    evicted.data = ckh->tab[evict_index].data;
    evicted_valid = true;

    // Insert new item in place of evicted
    ckh->tab[evict_index].key = current_key;
    ckh->tab[evict_index].data = current_data;
#ifdef CKH_COUNT
    ckh->nrelocs++;
#endif

    // Now try to reinsert the evicted item
    current_key = evicted.key;
    current_data = evicted.data;

    // Calculate new buckets for evicted item
    ckh->hash(current_key, hashes);
    bucket1 = hashes[0] & ((ZU(1) << ckh->lg_curbuckets) - 1);
    bucket2 = hashes[1] & ((ZU(1) << ckh->lg_curbuckets) - 1);

    // Choose the other bucket (not the one we just came from)
    current_bucket = (current_bucket == bucket1) ? bucket2 : bucket1;
}

// If we exhausted iterations, return failure
return true;

